css:
.d-dc{position:relative;width:100%;max-width:340px;height:190px;border:1px solid var(--line);border-radius:10px;background:var(--paper);overflow:hidden}
.d-dc-open{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);padding:6px 14px;border:1px solid var(--line);border-radius:999px;background:var(--bg);color:var(--ink);font:inherit;font-size:11px;cursor:pointer}
.d-dc-scrim{position:absolute;inset:0;background:var(--ink);opacity:0;pointer-events:none;transition:opacity 180ms var(--ease)}
.d-dc-sheet{position:absolute;left:0;right:0;bottom:0;padding:8px 16px 16px;border-radius:10px 10px 0 0;background:var(--bg);border-top:1px solid var(--line);transform:translateY(105%);transition:transform 280ms var(--ease-physical);touch-action:none;cursor:grab}
.d-dc-sheet.on{transform:none}
.d-dc-grip{display:block;width:34px;height:4px;margin:0 auto 8px;border-radius:999px;background:var(--line)}
.d-dc-sheet b{font-size:13px}
.d-dc-sheet p{margin:2px 0 0;font-size:11px;color:var(--muted)}

init:
root => {
  var sheet = root.querySelector('[data-sheet]');
  var scrim = root.querySelector('[data-scrim]');
  var open = root.querySelector('[data-open]');
  if (!sheet || !scrim || !open) return;
  var startY = 0, dy = 0, drag = false, H = 0;
  var setOpen = function (v) { sheet.style.transition = 'transform 280ms cubic-bezier(.34,1.56,.64,1)'; sheet.classList.toggle('on', v); scrim.style.opacity = v ? '.18' : '0'; };
  open.addEventListener('click', function () { setOpen(true); });
  sheet.addEventListener('pointerdown', function (e) { drag = true; startY = e.clientY; dy = 0; H = sheet.offsetHeight; sheet.style.transition = 'none'; sheet.setPointerCapture(e.pointerId); });
  sheet.addEventListener('pointermove', function (e) {
    if (!drag) return;
    dy = Math.max(0, e.clientY - startY);
    sheet.style.transform = 'translateY(' + dy.toFixed(1) + 'px)';
    scrim.style.opacity = String(Math.max(0, .18 * (1 - dy / H)));
  });
  var end = function () {
    if (!drag) return;
    drag = false;
    sheet.style.transition = 'transform 180ms cubic-bezier(.2,.75,.25,1)';
    if (dy > H * .25) { sheet.style.transform = 'translateY(105%)'; sheet.classList.remove('on'); scrim.style.opacity = '0'; }
    else { sheet.style.transform = ''; scrim.style.opacity = '.18'; setTimeout(function () { sheet.style.transition = 'transform 280ms cubic-bezier(.34,1.56,.64,1)'; }, 200); }
  };
  sheet.addEventListener('pointerup', end);
  sheet.addEventListener('pointercancel', end);
}
